import json,re,pathlib,html
root=pathlib.Path('curation/workspace/sjogren-disease')
records=json.load(open(root/'research/primary-records.json'))+json.load(open(root/'research/additional-records.json'))
papers={x['id']:x for x in records}
def plain(s):return re.sub(r'\s+',' ',re.sub('<[^>]*>',' ',s)).strip()
entities=[]
def ent(i,label,cls,desc,syn=[]):
 entities.append(dict(id=i,label=label,entityClass=cls,description=desc,synonyms=syn,externalIds=[]))
ent('entity-pdc','Plasmacytoid DCs','cell','Type I interferon-producing dendritic cells; human tissue observations and mouse depletion experiments are distinguished.',['pDC'])
ent('entity-ifn','IFN-α / type I IFN','cytokine','Type I interferon responses in Sjögren tissue and experimental systems.',['IFN-alpha'])
ent('entity-ifng','IFN-γ','cytokine','Type II interferon studied in salivary epithelial cultures.',['IFN-gamma'])
ent('entity-sjd-epithelium','Salivary gland epithelium','cell','Salivary epithelial cells studied in primary cultures and human gland tissue.',['SGEC'])
ent('entity-baff','BAFF / BLyS','cytokine','B-cell activating factor; epithelial inducibility, B-cell regulation and disease associations are context dependent.',['BAFF','BLyS'])
ent('entity-b_cells','B cells','cell','B lymphocytes in glandular infiltrates and BAFF experimental models.')
ent('entity-sjd-gc','Ectopic germinal centres','process','Organised glandular lymphoid structures detected in a subset of patients.',['GC-like structures'])
ent('entity-sjd-ssa','Anti-Ro/SSA and anti-La/SSB','antibody','Autoantibodies associated with RNA-binding antigens; not assumed pathogenic in every patient.',['anti-SSA','anti-SSB'])
ent('entity-debris','Apoptotic material','substrate','Material from necrotic or late apoptotic cells used in human-cell interferon-induction assays.')
ent('entity-complexes','Nucleic-acid immune complexes','immune_complex','RNA-containing immune complexes implicated by patient-serum and cell experiments.',['RNA immune complexes'])
ent('entity-sjd-gzmk-cd8','GZMK+ CD8+ T cells','cell','Glandular T-cell population associated with disease severity and epithelial engagement.')
ent('entity-sjd-gzmk','Granzyme K','protein','Effector molecule that activates epithelial interferon signalling in the inspected in-vitro study.',['GZMK'])
ent('entity-sjd-acinar-loss','Seromucous acinar-cell loss','process','Selective depletion of PRR4+CST3+WFDC2-negative acinar cells observed in human salivary tissue.')
ent('entity-sjd-aqp5','Aquaporin-5 distribution','process','Subcellular localisation of the AQP5 water channel; studies disagree about abnormal localisation in Sjögren glands.',['AQP5 localisation'])
ent('entity-sjd-saliva','Salivary secretory dysfunction','clinical_outcome','Reduced saliva secretion; experimental models and human tissue associations are not interchangeable.')
ent('entity-sjd-sicca','Dry eyes / dry mouth','clinical_outcome','Clinical sicca manifestations; direct lacrimal mechanisms remain incompletely curated.')
findings=[]
def add(i,pmid,s,o,p,text,q,system,typ='human_observational',interp='association',cat='supporting',limits=None,loc='Primary-report abstract via Europe PMC core record'):
 assert plain(q) in plain(papers[pmid]['abstractText']),(i,q)
 findings.append(dict(id='sjd-'+i,pmid=pmid,subject=s,object=o,predicate=p,text=text,quote=plain(q),quoteLocation=loc,studySystem=system,evidenceType=typ,causalInterpretation=interp,category=cat,limitations=limits or ['Abstract-level inspection; study methods and controls beyond the inspected material remain unverified. Observations do not establish disease-wide causality.'],sourceCheck=dict(checkedBy='Codex agent source inspection (not human or independent review)',checkedAt='2026-10-17')))
iv='Cultured SGECs from eight primary Sjögren patients and eight controls; 48-hour cytokine stimulation'
add('ifna-baff','16507175','entity-ifn','entity-baff','stimulates','IFN-alpha induced BAFF secretion in cultured salivary epithelial cells from primary Sjögren patients and controls.','Secretion of BAFF protein, undetectable at baseline, was significantly increased after IFN-alpha and IFN-gamma stimulation',iv,'human_in_vitro','mechanistic',limits=['Eight patients and eight controls; culture secretion is not clinical disease causation or treatment benefit. Patient-control differences were not significant.'])
add('ifng-baff','16507175','entity-ifng','entity-baff','stimulates','IFN-gamma induced BAFF secretion in primary salivary epithelial cultures.','Secretion of BAFF protein, undetectable at baseline, was significantly increased after IFN-alpha and IFN-gamma stimulation',iv,'human_in_vitro','mechanistic',limits=['Same culture cohort as IFN-alpha result; not independent replication.'])
add('epithelium-baff','16507175','entity-sjd-epithelium','entity-baff','produces','Salivary epithelial cells expressed and secreted BAFF after interferon stimulation.','capacity of SGECs to express and secrete BAFF after IFN stimulation',iv,'human_in_vitro','mechanistic',limits=['Induced production in culture; basal secretion was undetectable. Exact epithelial origin and stimulation methods inspected in PMC1526588 Results.'])
add('ifna-baff-null','16507175','entity-ifn','entity-baff','stimulates','BAFF protein secretion after interferon stimulation did not significantly differ between primary Sjögren and control cultures.','with no significant difference between pSS and controls',iv,'human_in_vitro','mechanistic','qualifying',['No significant patient-control difference; different within-group P values do not establish a between-group difference.'])
add('pdc-ifn','16477017','entity-pdc','entity-ifn','produces','IFN-producing plasmacytoid dendritic cells were detected in primary Sjögren salivary glands.','These IFN-producing cells were detected by immunohistochemistry in all patients with pSS, whereas none was observed in controls.','Human minor salivary-gland expression profiling and immunohistochemistry','human_observational','mechanistic',limits=['Tissue detection does not identify the exclusive source of type I IFN or establish temporal initiation.'])
add('ifn-epithelium','16477017','entity-ifn','entity-sjd-epithelium','activates','Interferons modulated IFN-inducible genes in salivary gland epithelial cells in vitro.','In vitro activation showed that these genes were effectively modulated by IFNs in salivary gland epithelial cells','Human salivary gland epithelial-cell experiments','human_in_vitro','mechanistic')
add('baff-bcells','11781351','entity-baff','entity-b_cells','promotes_survival_of','The BAFF-transgenic study identifies BAFF as a regulator of B-lymphocyte proliferation and survival.','specifically regulates B lymphocyte proliferation and survival','BAFF-transgenic mouse study with accompanying human observations','animal_experiment','mechanistic',limits=['BAFF regulation is stated in the primary report abstract; the proposed autoreactive-cell tolerance checkpoint mechanism remains an interpretation, not a demonstrated complete human circuit.'])
add('baff-saliva','11781351','entity-baff','entity-sjd-saliva','contributes_to','Aged BAFF-transgenic mice developed sialadenitis with decreased saliva production.','severe sialadenitis, decreased saliva production, and destruction of submaxillary glands','Aged BAFF-transgenic mice','animal_experiment','causal',limits=['Engineered BAFF overexpression; not evidence of sufficiency or necessity in primary human Sjögren disease.'])
add('bcells-gc','14613282','entity-b_cells','entity-sjd-gc','is_associated_with','Glandular germinal-centre-like structures contained organised T- and B-cell aggregates with proliferating cells and follicular dendritic-cell networks.','T and B cell aggregates with proliferating cells with a network of follicular dendritic cells','165 Sjögren minor salivary gland biopsies',limits=['17% had GC-like structures; abstract does not resolve primary versus associated disease for every participant. Morphology does not establish a universal disease stage.'])
add('gc-ssa','14613282','entity-sjd-gc','entity-sjd-ssa','is_associated_with','Local anti-Ro/SSA and anti-La/SSB autoantibody production was increased in biopsies with germinal-centre development.','local production of anti-Ro/SSA and anti-La/SSB autoantibodies was significantly increased','165 Sjögren gland biopsies; local antibody immunohistochemistry',limits=['Subset association, not proof that ectopic GCs are necessary for all serum autoantibodies. Primary-only composition unresolved in abstract.'])
add('baff-ssa','32506205','entity-baff','entity-sjd-ssa','is_associated_with','Soluble BAFF correlated with anti-La/SSB antibodies in the inspected primary Sjögren cohort.','Soluble levels of BAFF correlated with anti-La/SSB antibodies and disease duration.','MSG analysis in 29 subjects including primary Sjögren and nonspecific sialadenitis controls')
add('baff-gc','32506205','entity-baff','entity-sjd-gc','is_associated_with','BAFF and BAFF-R glandular expression was numerically higher in GC-positive primary Sjögren patients, without a significant difference from GC-negative patients.','BAFF and BAFF-R glandular expression levels were higher in pSS-GC(+) patients, without significant differences compared to pSS-GC(-) patients.','Cross-sectional MSG study in 29 subjects',limits=['Null group comparison; higher serum BAFF occurred in GC-negative patients. This is not evidence that greater BAFF causes GC formation.'])
add('baff-gc-null','32506205','entity-baff','entity-sjd-gc','is_associated_with','Serum BAFF was higher in GC-negative than GC-positive patients, qualifying a simple BAFF-to-GC progression model.','the pSS-GC(-) group showed higher sBAFF levels than pSS-GC(+) patients','Same 29-subject cross-sectional study','human_observational','association','qualifying',['Small mixed control/patient sample; serum and glandular compartments differ.'])
add('antibody-complex','15818675','entity-sjd-ssa','entity-complexes','forms','Autoantibodies to RNA-binding proteins combined with dying-cell material formed an interferon-inducing system consistent with RNA-containing immune complexes.','Autoantibodies to RNA-binding proteins, combined with material released by necrotic or late apoptotic cells, were potent inducers','Primary Sjögren sera and apoptotic/necrotic cell material added to normal human PBMCs','human_in_vitro','mechanistic',limits=['Does not establish that every anti-SSA/SSB specificity is pathogenic. Complex-mediated interpretation is from the inspected abstract.'])
add('debris-complex','15818675','entity-debris','entity-complexes','contributes_to','Necrotic or late apoptotic cell material contributed to the patient-serum interferon-inducing immune-complex system.','material released by necrotic or late apoptotic cells','Primary Sjögren sera and dying-cell material in human PBMC culture','human_in_vitro','mechanistic')
add('complex-pdc','15818675','entity-complexes','entity-pdc','activates','RNA-containing immune complexes activated plasmacytoid dendritic cells through RNA-dependent and Fc-gamma-RIIa-associated processes in culture.','RNA-containing immune complexes triggering PDCs by means of RNA and interaction with Fcgamma receptor IIa','Primary Sjögren serum / human PBMC interferon-induction experiments','human_in_vitro','mechanistic',limits=['Culture mechanism; assembled positive feedback with epithelial BAFF and local antibodies remains a cross-study hypothesis.'])
add('pdc-saliva','34780913','entity-pdc','entity-sjd-saliva','contributes_to','Early pDC depletion impeded secretory dysfunction in female NOD mice.','Depletion of pDCs impeded the development of SMG inflammation and secretory dysfunction.','Female NOD mice; anti-BST2/CD317 from 4 to 7 weeks, assessed at 10 weeks','animal_experiment','causal',limits=['Pre-onset mouse intervention; no evidence that established human secretory loss is reversible by pDC depletion.'])
add('cd8-acinar','41162286','entity-sjd-gzmk-cd8','entity-sjd-acinar-loss','is_associated_with','Human Sjögren glands showed both a rise in GZMK-positive CD8 T cells and selective loss of a seromucous acinar population.','a selective loss of PRR4⁺CST3⁺WFDC2⁻ seromucous acinar cells and a rise in GZMK⁺CD8⁺ T cells','Human minor salivary gland single-cell and spatial profiling',limits=['Co-occurrence and spatial localisation do not establish that these cells kill this acinar population in vivo.'])
add('cd8-gzmk','41162286','entity-sjd-gzmk-cd8','entity-sjd-gzmk','produces','Glandular GZMK-positive CD8 T cells displayed a cytotoxic transcriptional program and degranulated on ex-vivo stimulation.','GZMK⁺CD8⁺ T cells, which accumulate with disease severity, displayed a cytotoxic transcriptional program, degranulated upon stimulation ex vivo','Patient-derived glandular T cells with ex-vivo stimulation','human_in_vitro','mechanistic',limits=['GZMK-defined cell identity and degranulation do not prove that GZMK directly causes in-vivo acinar-cell loss.'])
add('gzmk-ifn','41162286','entity-sjd-gzmk','entity-ifn','activates','Functional assays found that GZMK activates epithelial interferon signalling in vitro.','Functional assays demonstrated that GZMK activates interferon signaling in vitro','Human primary epithelial cells and autologous T-cell co-cultures','human_in_vitro','mechanistic',limits=['Abstract-level in-vitro evidence; does not prove systemic interferon production or clinical causality.'])
add('acinar-epithelium','41162286','entity-sjd-acinar-loss','entity-sjd-epithelium','is_associated_with','Selective seromucous acinar-cell loss was part of epithelial remodeling observed in human Sjögren glands.','selective loss of PRR4⁺CST3⁺WFDC2⁻ seromucous acinar cells','Human salivary gland single-cell / spatial study',limits=['Anatomical association; secretory consequences were not quantified by this atomic finding.'])
add('epithelium-aqp5','11232635','entity-sjd-epithelium','entity-sjd-aqp5','is_associated_with','One small primary Sjögren biopsy study reported AQP5 redistribution from apical toward basal acinar membranes.','biopsies from SS patients revealed AQP5 primarily at the basal membranes of the acinus','Minor salivary biopsies: ten women with primary Sjögren and ten healthy volunteers, with other sicca comparators',limits=['Small immunohistochemistry study; a separate primary study did not reproduce altered distribution.'])
add('epithelium-aqp5-null','11741631','entity-sjd-epithelium','entity-sjd-aqp5','is_associated_with','A separate primary Sjögren study found no difference in AQP5 distribution or density relative to controls.','the distribution and density of aquaporin 5 in salivary glands does not differ between patients with PSS and those without','Human primary Sjögren salivary-gland immunofluorescence and immunoperoxidase study','human_observational','association','contradicting',['Conflicting human tissue findings; AQP5 mislocalisation is not a settled universal mechanism.'])
add('epithelium-saliva','11232635','entity-sjd-epithelium','entity-sjd-saliva','is_associated_with','The inspected primary report notes that salivary gland dysfunction may occur without glandular destruction.','glandular dysfunction also occurs without destruction','Human Sjögren salivary gland biopsy study; contextual clinical statement',limits=['Abstract contextual statement, not a quantified within-cohort functional analysis; does not establish a causal acinar-loss pathway.'])
add('saliva-sicca','34861168','entity-sjd-saliva','entity-sjd-sicca','is_associated_with','The primary Sjögren trial describes dry eyes and mouth as clinical manifestations of the disease being studied.','Sjögren\'s syndrome is an autoimmune disease characterised by dry eyes and mouth','Primary Sjögren phase 2b trial; clinical background statement',limits=['Descriptive clinical linkage, not an experimental test of salivary-to-lacrimal causation. Dry-eye mechanisms are an explicit curation gap.'])
